(()=>{var e=window.supermetry;if(document.currentScript.dataset.forms=="false")return;document.addEventListener("submit",t=>{var n=t.target;if(!n||n.tagName!="FORM"||n.getAttribute?.("data-supermetry-event")||e._tagged?.(n))return;e.track("Form: Submit",{form_id:(n.getAttribute("id")||"").slice(0,100),form_name:(n.getAttribute("name")||"").slice(0,100),action:(n.getAttribute("action")||"").split(/[?#]/)[0].slice(0,500)})},!0)})()